sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    /*
     * POST /eval/run
     *
     * Body:
     *   dataset_id       string  required  The dataset_id returned by /eval/generate.
     *   prompt_template  string  required  Template string with {key} placeholders matching
     *                                      the prompt_inputs_spec used during generation.
     *   extra_criteria   string  optional  Additional mandatory requirements for the grader.
     *
     * Response:
     *   {
     *     run_id, dataset_id, case_count,
     *     average_score,          // 0.0–10.0
     *     pass_rate,              // % of cases scoring >= 7
     *     cases: [
     *       { sys_id, scenario, score, reasoning, output }
     *     ]
     *   }
     */

    var body = request.body.data;
    var datasetId      = (body.dataset_id      || '').toString().trim();
    var promptTemplate = (body.prompt_template || '').toString();
    var extraCriteria  = (body.extra_criteria  || '').toString().trim();

    if (!datasetId) {
        response.setStatus(400);
        response.setBody({ error: 'dataset_id is required.' });
        return;
    }
    if (!promptTemplate) {
        response.setStatus(400);
        response.setBody({ error: 'prompt_template is required.' });
        return;
    }

    var evaluator = new x_146833_claudec_0.ClaudePromptEvaluator();
    var result    = evaluator.runEvaluation(datasetId, promptTemplate, extraCriteria);

    response.setStatus(200);
    response.setBody(result);

})(request, response);
